namespace lvk::dependencies { namespace { bool command(const std::string& value){const auto path=process::findOnPath(std::wstring(value.begin(),value.end()));return !path.empty()||std::filesystem::is_regular_file(value);} bool succeeds(const std::filesystem::path& executable,const std::wstring& arguments){const auto result=process::runHidden(executable,arguments);return result.started&&result.exitCode==0;} std::wstring q(const std::string& value){return L"\""+std::wstring(value.begin(),value.end())+L"\"";} } std::vector<Item> checkStatic(const config::Settings&s,const config::Profile*p){std::vector<Item> r;const bool llama=command(s.llamaCommand);r.push_back({"llama",llama?"Found":"llama command not found",llama});const auto docker=process::findOnPath(L"docker");const bool dc=!docker.empty();r.push_back({"Docker CLI",dc?"Found":"Docker CLI not found",dc});const bool model=p&&!p->model.empty()&&std::filesystem::is_regular_file(p->model);r.push_back({"Model",model?"Found":"GGUF model file not found",model});const bool ws=std::filesystem::exists(s.workspace);r.push_back({"Workspace",ws?"Found":"Workspace does not exist",ws});const bool image=dc&&succeeds(docker,L"image inspect "+q(s.dockerImage));r.push_back({"Docker image",image?"Ready":"Docker image is missing: "+s.dockerImage,image});return r;} std::vector<Item> checkRuntime(const config::Settings&s,bool llamaProcessRunning){std::vector<Item> r;const auto docker=process::findOnPath(L"docker");const bool engine=!docker.empty()&&succeeds(docker,L"info");r.push_back({"Docker Engine",engine?"Running":"Docker Engine is installed but not running",engine});const bool listening=port::isListening(s.host,s.port);const bool ownServer=listening&&llamaProcessRunning;r.push_back({"Port",ownServer?std::to_string(s.port)+" in use by server":listening?"Busy (another process)":"Free",ownServer||!listening});r.push_back({"Server",listening&&llamaProcessRunning?"Running":llamaProcessRunning?"Starting":"Stopped",listening&&llamaProcessRunning});return r;} }
